# name: high_alternation_pair_choice_rate
# description: Among trials where both sequences have alternation rate >= 0.6 and the rates differ, the proportion choosing the MORE alternating sequence; observed above the null means people penalise over-alternation less than the model's quadratic ideal-rate term implies, below means they penalise it more.
def test_statistic(df):
    def alt(s):
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(); ab = df["sequence_b"].map(m).to_numpy()
    sel = (aa >= 0.6) & (ab >= 0.6) & (np.abs(aa - ab) > 1e-9)
    if not sel.any():
        return 0.5
    cl = df["chose_left"].to_numpy()
    chose_more = np.where(aa > ab, cl, 1 - cl)
    return float(chose_more[sel].mean())

# name: streaky_pair_alternation_preference
# description: Among trials where both sequences have a longest run >= 4 and their alternation rates differ, the proportion choosing the MORE alternating sequence; observed above the null means that within streaky sequences people reward extra switches more than the model's quadratic ideal-rate term (flat near its far tail) predicts, below means less.
def test_statistic(df):
    def feats(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1), best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: feats(s) for s in u}
    aa = df["sequence_a"].map(lambda s: m[s][0]).to_numpy(); ab = df["sequence_b"].map(lambda s: m[s][0]).to_numpy()
    ra = df["sequence_a"].map(lambda s: m[s][1]).to_numpy(); rb = df["sequence_b"].map(lambda s: m[s][1]).to_numpy()
    sel = (ra >= 4) & (rb >= 4) & (np.abs(aa - ab) > 1e-9)
    if not sel.any():
        return 0.5
    cl = df["chose_left"].to_numpy()
    chose_more = np.where(aa > ab, cl, 1 - cl)
    return float(chose_more[sel].mean())

# name: low_streak_maxrun_preference
# description: Among trials where both sequences have a longest run <= 3 and the longest runs differ, the proportion choosing the sequence with the SHORTER longest run; observed below the null means people do not penalise short streaks (2-3) as much as the model's linear longest-run term implies (a threshold-like streak aversion), above means they penalise them more.
def test_statistic(df):
    def mr(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: mr(s) for s in u}
    ra = df["sequence_a"].map(m).to_numpy(); rb = df["sequence_b"].map(m).to_numpy()
    sel = (ra <= 3) & (rb <= 3) & (ra != rb)
    if not sel.any():
        return 0.5
    cl = df["chose_left"].to_numpy()
    chose_short = np.where(ra < rb, cl, 1 - cl)
    return float(chose_short[sel].mean())

# name: run_length_evenness_at_equal_runs
# description: Among trials where both sequences have the same number of runs (same alternation rate) but different run-length standard deviations, the proportion choosing the sequence whose run lengths are MORE EVEN (lower SD, e.g. HHHTTHHH over HTHHHHHH); observed above the null means people prefer evenly spread runs more than the model's longest-run, final-run and variety terms predict, below means they prefer lopsided run structure more.
def test_statistic(df):
    def sd(s):
        runs = []; cur = 1
        for x, y in zip(s, s[1:]):
            if x == y:
                cur += 1
            else:
                runs.append(cur); cur = 1
        runs.append(cur)
        return len(runs), float(np.std(runs))
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: sd(s) for s in u}
    fa = np.array([m[s] for s in df["sequence_a"]]); fb = np.array([m[s] for s in df["sequence_b"]])
    sel = (fa[:, 0] == fb[:, 0]) & (np.abs(fa[:, 1] - fb[:, 1]) > 1e-9)
    if not sel.any():
        return 0.5
    cl = df["chose_left"].to_numpy()
    chose_even = np.where(fa[:, 1] < fb[:, 1], cl, 1 - cl)
    return float(chose_even[sel].mean())

# name: late_minus_early_alternation_preference
# description: Rate of choosing the more alternating sequence (trials where alternation rates differ) in each participant's second half of trials minus the first half; positive observed above the null means preferences for alternation strengthen over the session (learning/sharpening) beyond the model's time-invariant judgement, below means they fade (fatigue/increasing guessing).
def test_statistic(df):
    def alt(s):
        return sum(x != y for x, y in zip(s, s[1:])) / (len(s) - 1)
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: alt(s) for s in u}
    aa = df["sequence_a"].map(m).to_numpy(); ab = df["sequence_b"].map(m).to_numpy()
    cl = df["chose_left"].to_numpy()
    med = df.groupby("participant_id")["trial_index"].transform("median").to_numpy()
    late = df["trial_index"].to_numpy() > med
    sel = np.abs(aa - ab) > 1e-9
    chose_more = np.where(aa > ab, cl, 1 - cl)
    e = sel & ~late; l = sel & late
    if not e.any() or not l.any():
        return 0.0
    return float(chose_more[l].mean() - chose_more[e].mean())

# name: streak_aversion_participant_sd
# description: SD across participants of each person's rate of choosing the sequence with the shorter longest run (over trials where the longest runs differ); observed above the null means people differ in streak aversion more than the model's personal longest-run weights and lapse rates produce, below means the model over-produces this individual variation.
def test_statistic(df):
    def mr(s):
        best = cur = 1
        for x, y in zip(s, s[1:]):
            cur = cur + 1 if x == y else 1
            best = max(best, cur)
        return best
    u = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    m = {s: mr(s) for s in u}
    ra = df["sequence_a"].map(m).to_numpy(); rb = df["sequence_b"].map(m).to_numpy()
    sel = ra != rb
    if not sel.any():
        return 0.0
    cl = df["chose_left"].to_numpy()
    chose_short = np.where(ra < rb, cl, 1 - cl)
    rates = pd.Series(chose_short[sel]).groupby(df["participant_id"].to_numpy()[sel]).mean()
    if len(rates) < 2:
        return 0.0
    return float(rates.std())
